USE [JamunaBankProcurement];
GO
/* Repair pending Concern Division workflows created without the matching current
   Concern Official assignment. This is intentionally idempotent. */
UPDATE a
SET a.IS_CURRENT=0,a.RELEASED_DATE=SYSUTCDATETIME()
FROM dbo.REQUISITION_ASSIGNMENT a
JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=a.REQUISITION_ID
JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID
JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1
WHERE w.CURRENT_STAGE='CONCERN_DIVISION' AND w.CURRENT_STATUS='PENDING' AND w.COMPLETED_DATE IS NULL
  AND a.IS_CURRENT=1
  AND (a.ASSIGNMENT_TYPE<>'CONCERN_OFFICIAL' OR a.ASSIGNED_TO_ORG_UNIT_ID IS NULL OR a.ASSIGNED_TO_ORG_UNIT_ID<>s.ORG_UNIT_ID);

INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,ASSIGNED_TO_ORG_UNIT_ID,CREATED_BY)
SELECT w.REQUISITION_ID,'CONCERN_OFFICIAL',s.ORG_UNIT_ID,'workflow-assignment-repair'
FROM dbo.WORKFLOW_INSTANCE w
JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID
JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1
JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID AND h.CURRENT_STATUS='IN_WORKFLOW' AND h.IS_ACTIVE=1
WHERE w.CURRENT_STAGE='CONCERN_DIVISION' AND w.CURRENT_STATUS='PENDING' AND w.COMPLETED_DATE IS NULL
  AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT a WHERE a.REQUISITION_ID=w.REQUISITION_ID AND a.ASSIGNMENT_TYPE='CONCERN_OFFICIAL' AND a.ASSIGNED_TO_ORG_UNIT_ID=s.ORG_UNIT_ID AND a.IS_CURRENT=1);
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetDetail @RequisitionId BIGINT,@EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;DECLARE @requester VARCHAR(30);SELECT @requester=h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_OFFICIAL o ON o.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND o.EMPLOYEE_ID=@EmployeeId AND o.IS_ACTIVE=1 AND o.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(o.EFFECTIVE_TO IS NULL OR o.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())) WHERE h.REQUISITION_ID=@RequisitionId AND h.CURRENT_STATUS='IN_WORKFLOW'AND h.IS_ACTIVE=1 AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL;IF @requester IS NULL BEGIN SELECT TOP(0) REQUISITION_ID,REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,CAST(''AS NVARCHAR(200))ORG_UNIT_NAME,REQUESTED_DATE,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CURRENT_STATUS FROM dbo.REQUISITION_HEADER;RETURN;END;EXEC dbo.usp_Requisition_GetMakerDetail @RequisitionId,@requester;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetReviewContext @RequisitionId BIGINT,@EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;SELECT r.WORKFLOW_RULE_ID,r.RULE_CODE,r.RULE_NAME,w.CURRENT_STAGE,r.DESTINATION_AFTER_CONCERN MATRIX_DESTINATION,d.CONCERN_DIVISION_ID,o.ORG_UNIT_NAME CONCERN_DIVISION_NAME FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP d ON d.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=d.ORG_UNIT_ID JOIN dbo.CONCERN_DIVISION_OFFICIAL f ON f.CONCERN_DIVISION_ID=d.CONCERN_DIVISION_ID AND f.EMPLOYEE_ID=@EmployeeId AND f.IS_ACTIVE=1 AND f.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(f.EFFECTIVE_TO IS NULL OR f.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())) WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetPending @EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,r.CONCERN_DIVISION_ID,ou.ORG_UNIT_NAME CONCERN_DIVISION_NAME,u.DISPLAY_NAME REQUESTED_BY_NAME,(SELECT COUNT(*)FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)ITEM_COUNT FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1 JOIN dbo.ORG_UNIT ou ON ou.ORG_UNIT_ID=s.ORG_UNIT_ID JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID JOIN dbo.CONCERN_DIVISION_OFFICIAL o ON o.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND o.EMPLOYEE_ID=@EmployeeId AND o.IS_ACTIVE=1 AND o.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(o.EFFECTIVE_TO IS NULL OR o.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))WHERE w.CURRENT_STAGE='CONCERN_DIVISION'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL AND h.CURRENT_STATUS='IN_WORKFLOW'AND h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT a WHERE a.REQUISITION_ID=h.REQUISITION_ID AND a.ASSIGNMENT_TYPE='CONCERN_OFFICIAL'AND a.IS_CURRENT=1 AND a.ASSIGNED_TO_ORG_UNIT_ID=s.ORG_UNIT_ID)ORDER BY h.REQUESTED_DATE;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_VerifyComplete @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;DECLARE @next VARCHAR(40);SELECT @next=r.DESTINATION_AFTER_CONCERN FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.COMPLETED_DATE IS NULL;IF @next NOT IN('READY_FOR_PROCUREMENT','PROCUREMENT_AUTHORITY')BEGIN SELECT'004'RESULT_CODE,N'No valid matrix-defined destination exists after Concern processing.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;DECLARE @result TABLE(RESULT_CODE VARCHAR(3),RESULT_MESSAGE NVARCHAR(4000),ENTITY_ID BIGINT,REFERENCE_NO VARCHAR(100));INSERT @result EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_DIVISION','CONCERN_VERIFY_COMPLETE','CONCERN_OFFICIAL',@next,@Remarks,@BatchReferenceId;SELECT RESULT_CODE,RESULT_MESSAGE,ENTITY_ID,CASE WHEN RESULT_CODE='000'THEN @next ELSE REFERENCE_NO END REFERENCE_NO FROM @result;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_ForwardToAuthority @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;DECLARE @division BIGINT;SELECT @division=r.CONCERN_DIVISION_ID FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.COMPLETED_DATE IS NULL;IF @division IS NULL BEGIN SELECT'004'RESULT_CODE,N'Requisition is not pending with a Concern Division.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;IF NOT EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_AUTHORITY WHERE CONCERN_DIVISION_ID=@division AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))BEGIN SELECT'001'RESULT_CODE,N'No active authority is configured for this Concern Division.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_DIVISION','CONCERN_FORWARD_TO_AUTHORITY','CONCERN_OFFICIAL','CONCERN_AUTHORITY',@Remarks,@BatchReferenceId;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_TerminalOrReturn @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Action VARCHAR(20),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;IF @Action NOT IN('RETURN','NOT_RECOMMEND')OR NULLIF(LTRIM(RTRIM(@Remarks)),'')IS NULL THROW 51000,'A valid action and remarks are required.',1;DECLARE @rule BIGINT,@division BIGINT;SELECT @rule=w.WORKFLOW_RULE_ID,@division=r.CONCERN_DIVISION_ID FROM dbo.WORKFLOW_INSTANCE w WITH(UPDLOCK,HOLDLOCK)JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL;IF @rule IS NULL THROW 51003,'Requisition is not pending with a Concern Division.',1;IF NOT EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_OFFICIAL WHERE CONCERN_DIVISION_ID=@division AND EMPLOYEE_ID=@ActorEmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))THROW 51002,'Actor is not an active official for this Concern Division.',1;IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STATUS='IN_WORKFLOW'AND IS_ACTIVE=1)THROW 51003,'Invalid workflow state.',1;DECLARE @to VARCHAR(40)=CASE WHEN @Action='RETURN'THEN'PROCUREMENT_OFFICER'ELSE'END'END,@actionType VARCHAR(50)=CASE WHEN @Action='RETURN'THEN'CONCERN_RETURN'ELSE'CONCERN_NOT_RECOMMEND'END;UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1;IF @Action='RETURN'INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,CREATED_BY)VALUES(@RequisitionId,'PROCUREMENT_OFFICER_POOL',@ActorEmployeeId);UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS=CASE WHEN @Action='RETURN'THEN'IN_WORKFLOW'ELSE'NOT_RECOMMENDED'END,MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId;UPDATE dbo.WORKFLOW_INSTANCE SET CURRENT_STAGE=@to,CURRENT_OWNER_TYPE=CASE WHEN @Action='RETURN'THEN'ROLE_POOL'ELSE'NONE'END,CURRENT_OWNER_EMPLOYEE_ID=NULL,CURRENT_OWNER_ORG_UNIT_ID=NULL,CURRENT_STATUS=CASE WHEN @Action='RETURN'THEN'PENDING'ELSE'COMPLETED'END,COMPLETED_DATE=CASE WHEN @Action='NOT_RECOMMEND'THEN SYSUTCDATETIME()END,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STAGE='CONCERN_DIVISION'AND COMPLETED_DATE IS NULL;INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@actionType,@ActorEmployeeId,'CONCERN_OFFICIAL','CONCERN_DIVISION',@to,@Remarks,@BatchReferenceId);INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@rule,'CONCERN_DIVISION',@to,@actionType,@ActorEmployeeId,@Remarks,@BatchReferenceId);COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,@to REFERENCE_NO;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51002 THEN'003'WHEN 51003 THEN'004'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_Return @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;EXEC dbo.usp_ConcernDivision_TerminalOrReturn @RequisitionId,@ActorEmployeeId,'RETURN',@Remarks,@BatchReferenceId;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_NotRecommend @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;EXEC dbo.usp_ConcernDivision_TerminalOrReturn @RequisitionId,@ActorEmployeeId,'NOT_RECOMMEND',@Remarks,@BatchReferenceId;END;
GO
